/* Site copy translations. Original Figma assets remain unchanged. */
(function(){
  'use strict';
  var copy={"Stone Speech Temple of the Light Gap":{"zh":"石之语：光隙神殿","en":"Stone Speech\nTemple of the Light Gap"},"The starting point of this project is my long-time admiration for video game creator Fumito Ueda—I’ve always loved his works like 《ICO》, 《Shadow of the Colossus》, and 《The Last Guardian》. This piece draws inspiration from analyzing the \"ruin aesthetics\" of the temple in Ueda’s 《The Last Guardian》; however, my core goal isn’t to replicate his style. Instead, I aim to deliver a fresh expression through technical reconstruction and conceptual refinement. I abandoned ready-made materials and chose to use a completely self-developed shader as the core creative tool. The texture of every inch of the stone wall in the scene, the moist spreading trajectory of moss, and the light green tone of light scattering in the air are all controlled and \"calibrated\" by me through algorithmic coding. This allows materials to go beyond visual simulation and be endowed with emotional parameters, becoming the first storyteller to create immersion.":{"zh":"这个项目源于我对游戏创作者上田文人的长期喜爱，他的《古堡迷踪》《旺达与巨像》和《最后的守护者》一直令我着迷。我分析了《最后的守护者》中神殿的废墟美学，但目的并非复刻其风格，而是通过技术重构与概念提炼，形成新的表达。\n我没有采用现成材质，而是以完全自主开发的Shader作为核心创作工具。石墙的纹理、苔藓湿润蔓延的轨迹，以及空气中淡绿色的散射光，都通过算法进行控制和调校。材质由此超越外观模拟，承载情绪，成为营造沉浸感的叙事媒介。","en":"The starting point of this project is my long-time admiration for video game creator Fumito Ueda—I’ve always loved his works like 《ICO》, 《Shadow of the Colossus》, and 《The Last Guardian》. This piece draws inspiration from analyzing the \"ruin aesthetics\" of the temple in Ueda’s 《The Last Guardian》; however, my core goal isn’t to replicate his style. Instead, I aim to deliver a fresh expression through technical reconstruction and conceptual refinement.\nI abandoned ready-made materials and chose to use a completely self-developed shader as the core creative tool. The texture of every inch of the stone wall in the scene, the moist spreading trajectory of moss, and the light green tone of light scattering in the air are all controlled and \"calibrated\" by me through algorithmic coding. This allows materials to go beyond visual simulation and be endowed with emotional parameters, becoming the first storyteller to create immersion."},"Temple of the Light Gap":{"zh":"光隙神殿","en":"Temple of the Light Gap"},"Other Views":{"zh":"其他视角","en":"Other Views"},"In the end, the cave entrance became the only director, and the light became the flowing pointer. The entire scene is a precise ensemble of materials, light and shadow, and spatial rhythm, aimed at inviting viewers to step into it and experience a pure introspection and imagination in the tranquility generated by code.":{"zh":"最终，洞口成为引导视线的舞台，光线成为流动的指针。整个场景由材质、光影与空间节奏共同构成，邀请观者进入由代码营造的宁静，展开思考与想象。","en":"In the end, the cave entrance became the only director, and the light became the flowing pointer. The entire scene is a precise ensemble of materials, light and shadow, and spatial rhythm, aimed at inviting viewers to step into it and experience a pure introspection and imagination in the tranquility generated by code."},"Scene conception":{"zh":"场景构思","en":"Scene conception"},"Build a scene sketch":{"zh":"搭建场景草图","en":"Build a scene sketch"},"Ancient Greek goddess":{"zh":"古希腊女神","en":"Ancient Greek goddess"},"draft":{"zh":"草稿","en":"draft"},"Inspiration sources and key items for component scenes":{"zh":"场景灵感来源与关键元素","en":"Inspiration sources and key items for component scenes"},"The sculptures of ancient Greek and Roman goddesses are frequently seen in game scenes":{"zh":"古希腊、古罗马女神雕像经常出现在游戏场景中。","en":"The sculptures of ancient Greek and Roman goddesses are frequently seen in game scenes"},"Mist permeates the entire forest, and sunlight refracts onto the leaves of the forest":{"zh":"雾气弥漫森林，阳光穿透树叶。","en":"Mist permeates the entire forest, and sunlight refracts onto the leaves of the forest"},"Plant":{"zh":"植物","en":"Plant"},"Image source":{"zh":"图片来源","en":"Image source"},"Ancient stone":{"zh":"古老的石块","en":"Ancient stone"},"Temple":{"zh":"神殿","en":"Temple"},"Plants in the forest exhibit a unique transparent texture when exposed to sunlight.":{"zh":"森林中的植物在阳光下呈现出独特的透光质感。","en":"Plants in the forest exhibit a unique transparent texture when exposed to sunlight."},"The preliminary plan envisions a scene with stones/plants/water/lights. The sketch above is generated using Stable Diffusion below":{"zh":"初步方案包含石块、植物、水与灯光。上方草图使用 Stable Diffusion 生成。","en":"The preliminary plan envisions a scene with stones/plants/water/lights. The sketch above is generated using Stable Diffusion below"},"The moss covered stones are also a part of adding atmosphere to the scene":{"zh":"覆盖苔藓的石块也是营造氛围的重要元素。","en":"The moss covered stones are also a part of adding atmosphere to the scene"},"In the atmosphere of The Wizard of Oz, there is always a mysterious temple appearing at the end of the forest.":{"zh":"在绿野仙踪般的氛围中，森林尽头总有一座神秘的神殿。","en":"In the atmosphere of The Wizard of Oz, there is always a mysterious temple appearing at the end of the forest."},"Process of setting up a scene":{"zh":"场景搭建流程","en":"Process of setting up a scene"},"Fab assets used - import UE5.5 first and then import Unity":{"zh":"使用 Fab 资产：先导入 UE5.5，再转入 Unity。","en":"Fab assets used - import UE5.5 first and then import Unity"},"Using plugins to transfer assets to Unity: lighting errors, poor shader effect, chaotic scene":{"zh":"通过插件将资产转入 Unity：出现灯光错误、着色效果不佳及场景混乱。","en":"Using plugins to transfer assets to Unity: lighting errors, poor shader effect, chaotic scene"},"Replace with your own shader, turn off all point light sources, and re plan the lighting":{"zh":"替换为自研Shader，关闭所有点光源，重新规划灯光。","en":"Replace with your own shader, turn off all point light sources, and re plan the lighting"},"Adjust the overall effect":{"zh":"调整整体效果","en":"Adjust the overall effect"},"Adjust the material+make PBR support BakedGI and ShadowMap":{"zh":"调整材质，并让 PBR 支持烘焙全局光照与阴影贴图。","en":"Adjust the material+make PBR support BakedGI and ShadowMap"},"Fine tune Shader, material, and lighting; complete":{"zh":"微调Shader、材质和灯光，完成场景。","en":"Fine tune Shader, material, and lighting; complete"},"TECHNICAL DETAILS":{"zh":"技术细节","en":"TECHNICAL  DETAILS"},"Sculpture / White model":{"zh":"雕像／白模","en":"Sculpture / White model"},"Sculpture: Ice Shader":{"zh":"雕像：冰材质Shader","en":"Sculpture: Ice Shader"},"Sculpture & Ice Material":{"zh":"雕像与冰材质","en":"Sculpture & Ice Material"},"The initial plan was to use opaque ice and parallax effect, but the effect was not ideal in the current scene.So it was changed to semi transparent ice: 3S sampling+MatCap reflection+Blur screen color was used":{"zh":"最初计划采用不透明冰和视差效果，但在当前场景中的表现不理想。因此改用半透明冰，结合三次采样、MatCap 反射和屏幕颜色模糊。","en":"The initial plan was to use opaque ice and parallax effect, but the effect was not ideal in the current scene.So it was changed to semi transparent ice: 3S sampling+MatCap reflection+Blur screen color was used"},"Sculpture: Problems encountered":{"zh":"雕像：遇到的问题","en":"Sculpture: Problems encountered"},"The final statue was given a colored image as the base and a Icy scene image as a reflection for MatCap.":{"zh":"最终为雕像使用彩色图作为底色，并以冰雪场景图作为 MatCap 反射来源。","en":"The final statue was given a colored image as the base and a Icy scene image as a reflection for MatCap."},"So it was changed to semi transparent ice: 3S sampling+MatCap reflection+Blur screen color was used":{"zh":"因此改用半透明冰：结合三次采样、MatCap 反射和屏幕颜色模糊。","en":"So it was changed to semi transparent ice: 3S sampling+MatCap reflection+Blur screen color was used"},"To retain the details of the high-poly model on the low-poly mesh, a normal map is required, so a normal blending is needed. At the same time, ice rendering for Transparent also has rendering queue issues to deal with compared to other Opaque renderings.":{"zh":"为了在低模上保留高模细节，需要使用法线贴图，并进行法线混合。同时，半透明冰相较于不透明材质，还需要处理渲染队列问题。","en":"To retain the details of the high-poly model on the low-poly mesh, a normal map is required, so a normal blending is needed. At the same time, ice rendering for Transparent also has rendering queue issues to deal with compared to other Opaque renderings."},"PBR Shader":{"zh":"PBR Shader","en":"PBR Shader"},"Foliage PBR Shader":{"zh":"植物 PBR Shader","en":"Foliage PBR Shader"},"Firstly, I need a traditional PBR framework to render ordinary objects (opaque objects without vertex motion) in the entire scene. I use Disney's (Cook Tolerance+IBL) writing method, which divides the diffuse reflection by π compared to Unity's built-in division, following energy conservation.":{"zh":"首先需要一套传统 PBR 框架，用于渲染场景中的普通物体，即不带顶点运动的不透明物体。我采用迪士尼的着色思路，结合 Cook–Torrance 模型与基于图像的照明，将漫反射除以 π，以满足能量守恒。","en":"Firstly, I need a traditional PBR framework to render ordinary objects (opaque objects without vertex motion) in the entire scene. I use Disney's (Cook Tolerance+IBL) writing method, which divides the diffuse reflection by π compared to Unity's built-in division, following energy conservation."},"Foliage PBR (as a built-in SpeedTree foliage shader in Unity, self-written on the right, with the same model)":{"zh":"植物 PBR 对比：同一模型，左侧为 Unity 内置 SpeedTree 植物Shader，右侧为自研版本。","en":"Foliage PBR (as a built-in SpeedTree foliage shader in Unity, self-written on the right, with the same model)"},"Scattering effect":{"zh":"散射效果","en":"Scattering effect"},"Scattering Effect: When backlit, there is a leaf transmission effect":{"zh":"散射效果：逆光时呈现树叶透光感。","en":"Scattering Effect: When backlit, there is a leaf transmission effect"},"Object PBR (PRDF+IBL) (non-metallic) (built-in on the left, self-written on the right)":{"zh":"物体 PBR：非金属，结合反射分布函数与基于图像的照明；左侧内置，右侧自研。","en":"Object PBR (PRDF+IBL) (non-metallic) (built-in on the left, self-written on the right)"},"Implementation: Reverse SH":{"zh":"实现：反向球谐光照","en":"Implementation: Reverse SH"},"Implementation: Scatter":{"zh":"实现：散射","en":"Implementation: Scatter"},"Object PBR (PRDF+IBL) (Metal Object) (built-in on the left, self-written on the right)":{"zh":"物体 PBR：金属，结合反射分布函数与基于图像的照明；左侧内置，右侧自研。","en":"Object PBR (PRDF+IBL) (Metal Object) (built-in on the left, self-written on the right)"},"Optimization method: Reference":{"zh":"优化方法：参考资料","en":"Optimization method: Reference"},"Procedural Animation (1) the main bending, which animates the entire vegetation along the wind direction;and (2) the detail bending, which animates the leaves. A wind vector is computed per-instance,in world space, by summing up the wind forces affecting the instance.A wind area can be a directional or an omnidirectional wind source.":{"zh":"程序化动画\n第一部分是主弯曲，使整株植被沿风向运动；第二部分是细节弯曲，使叶片产生运动。每个实例都在世界空间中累加所受风力，得到风向量。风场可以是定向的，也可以是全向的。","en":"Procedural Animation\n(1) the main bending, which animates the entire vegetation along the wind direction;and (2) the detail bending, which animates the leaves. A wind vector is computed per-instance,in world space, by summing up the wind forces affecting the instance.A wind area can be a directional or an omnidirectional wind source."},"PBR, Foliage & Water":{"zh":"PBR、植物与水材质","en":"PBR, Foliage & Water"},"WATER SHADER":{"zh":"水面Shader","en":"WATER SHADER"},"Wind Animation: Originally used the same simple multiple Sin and Cos stacking algorithm as my previouos project “Lycoris”, but found that the effect in the scene was very unnatural":{"zh":"风力动画：\n最初沿用之前《彼岸花》项目中多个正弦与余弦叠加的简单算法，但在当前场景中显得不够自然。","en":"Wind Animation: \nOriginally used the same simple multiple Sin and Cos stacking algorithm as my previouos project “Lycoris”, but found that the effect in the scene was very unnatural"},"WATER: The final effect of water":{"zh":"水面：\n最终水面效果","en":"WATER: \nThe final effect of water"},"It can be seen that only the top left and bottom right directions in the picture have shaking, while the other two directions are almost stationary":{"zh":"图中只有左上和右下方向在晃动，另外两个方向几乎静止。","en":"It can be seen that only the top left and bottom right directions in the picture have shaking, while the other two directions are almost stationary"},"The effect in the scene":{"zh":"场景中的效果","en":"The effect in the scene"},"Optimization: Research on existing plant aerodynamic practices, ultimately using the islanding crisis approach: Main Bend+Detail Bending":{"zh":"优化：研究现有植物空气动力学方案，最终采用《孤岛危机》的主弯曲与细节弯曲方法。","en":"Optimization: Research on existing plant aerodynamic practices, ultimately using the islanding crisis approach: Main Bend+Detail Bending"},"After optimization:":{"zh":"优化后：","en":"After optimization:"},"Parameter control:":{"zh":"参数控制：","en":"Parameter control:"},"Main Bend: Overall Deformation":{"zh":"主弯曲：整体形变","en":"Main Bend: Overall Deformation"},"Detail Bend Effect: Imitate the natural shaking of leaves":{"zh":"细节弯曲：模拟叶片自然晃动","en":"Detail Bend Effect: Imitate the natural shaking of leaves"},"This figure is only for algorithm performance reference, and the actual fluctuation value will be given very small":{"zh":"此图仅用于展示算法效果，实际应用时会将波动幅度设得很小。","en":"This figure is only for algorithm performance reference, and the actual fluctuation value will be given very small"},"WATER SHADER：surface texture":{"zh":"水面Shader：表面纹理","en":"WATER SHADER：surface texture"},"REFRACTION & REFLECTION":{"zh":"折射与反射","en":"REFRACTION & REFLECTION"},"Wave Ripple: Initially, I planned to use the traditional Flow Map writing method, but the effect was not ideal":{"zh":"水面波纹：最初计划使用传统流向贴图方案，但效果不理想。","en":"Wave Ripple: Initially, I planned to use the traditional Flow Map writing method, but the effect was not ideal"},"Refraction: Due to the many stones and grass embedded in the water in the scene, it is necessary to refract them.":{"zh":"折射：场景中的水面包含大量石块和草，需要对它们进行折射。","en":"Refraction: Due to the many stones and grass embedded in the water in the scene, it is necessary to refract them."},"There was no refraction originally (it is best to cut the right half of the image below, which is the most obvious):":{"zh":"未添加折射时：下图右半部分的差异最明显。","en":"There was no refraction originally (it is best to cut the right half of the image below, which is the most obvious):"},"There is refraction":{"zh":"添加折射后","en":"There is refraction"},"Optimization: After switching to FFT-based heightmap generation, the water surface appears more three-dimensional":{"zh":"优化：改为基于 FFT 生成高度图后，水面更具立体感。","en":"Optimization: After switching to FFT-based heightmap generation, the water surface appears more three-dimensional"},"VOLUMETRIC FOG/LIGHT : RAYMARCHING":{"zh":"体积雾与体积光：光线步进","en":"VOLUMETRIC FOG/LIGHT : RAYMARCHING"},"Optimization Specific operation: Use Blender's Ocean function to bake a Flipbook image of Ocean Wave Animation with Normal and Height, and sample and Flipbook animation in Shader":{"zh":"优化实现：使用 Blender 的海洋功能烘焙包含法线与高度信息的波浪动画序列图，并在Shader中采样、播放序列帧动画。","en":"Optimization Specific operation: Use Blender's Ocean function to bake a Flipbook image of Ocean Wave Animation with Normal and Height, and sample and Flipbook animation in Shader"},"It can also be sharpened or softened by adjusting parameters, adjusting the distance between the ice and the edge, or whether the density changes with distance":{"zh":"还可以调节参数使边缘锐利或柔和，控制冰与边缘的距离，以及密度是否随距离变化。","en":"It can also be sharpened or softened by adjusting parameters, adjusting the distance between the ice and the edge, or whether the density changes with distance"},"Technical points: Ray AABB intersection calculation+RayMarching step sampling core loop (as shown in the code)+fog density calculation+3D noise sampling":{"zh":"技术要点：光线与轴对齐包围盒的相交计算、光线步进采样核心循环、雾密度计算及三维噪声采样。","en":"Technical points: Ray AABB intersection calculation+RayMarching step sampling core loop (as shown in the code)+fog density calculation+3D noise sampling"},"There was no specular reflection originally":{"zh":"未添加镜面反射时","en":"There was no specular reflection originally"},"Increase specular reflection, reflect colors in the scene, and perform distortion on colors through class refraction":{"zh":"增加镜面反射，反映场景颜色，并通过类似折射的处理使颜色发生扭曲。","en":"Increase specular reflection, reflect colors in the scene, and perform distortion on colors through class refraction"},"Capture scene colors using C # scripts":{"zh":"使用 C# 脚本捕获场景颜色","en":"Capture scene colors using C # scripts"},"EDITOR TOOLS USED":{"zh":"使用的编辑器工具","en":"EDITOR TOOLS USED"},"01 ShaderGUI：C#":{"zh":"01 Shader参数界面：C#","en":"01  ShaderGUI：C#"},"02 Batch scene management tool":{"zh":"02 场景批量管理工具","en":"02  Batch scene management tool"},"As I added more features to the Shader during development, the parameter count grew—making them hard to manage. Additionally, texture setups vary per material (some combine multiple textures into one input), so the Shader needs to sample different textures for the same calculation based on the material’s configuration. Since Unity URP’s default Shader interface doesn’t auto-hide unused parameters, I spent a week implementing a custom ShaderGUI. This ShaderGUI organizes parameters into collapsible sections in the material inspector: specific parameters can be shown/hidden via toggles, and the MaterialProperty interface is used to group Shader features logically.":{"zh":"随着开发中不断增加Shader功能，参数数量也越来越多，管理变得困难。此外，不同材质的纹理配置并不相同，有时会把多个纹理合并到同一输入中，因此Shader需要根据配置采样不同纹理来完成同一种计算。\nUnity URP 的默认界面不会自动隐藏未使用的参数，因此我花了一周实现自定义Shader参数界面。\n界面通过可折叠区域组织参数，利用开关显示或隐藏特定参数，并通过材质属性接口对功能进行分组。","en":"As I added more features to the Shader during development, the parameter count grew—making them hard to manage. Additionally, texture setups vary per material (some combine multiple textures into one input), so the Shader needs to sample different textures for the same calculation based on the material’s configuration.\nSince Unity URP’s default Shader interface doesn’t auto-hide unused parameters, I spent a week implementing a custom ShaderGUI.\nThis ShaderGUI organizes parameters into collapsible sections in the material inspector: specific parameters can be shown/hidden via toggles, and the MaterialProperty interface is used to group Shader features logically."},"One-click light renaming (by light type) and grouping – streamlines organization of lights (adapted to manage UE-imported assets)":{"zh":"按光源类型一键重命名并分组，简化灯光管理，适配从 UE 导入的资产。","en":"One-click light renaming (by light type) and grouping – streamlines organization of lights (adapted to manage UE-imported assets)"},"Disable Function":{"zh":"禁用功能","en":"Disable Function"},"Method for implementing this feature: Define a GUI script, an expression script, and a summarized Shader editor script":{"zh":"实现方式：定义界面脚本、表达式脚本和统一的Shader编辑器脚本。","en":"Method for implementing this feature: Define a GUI script, an expression script, and a summarized Shader editor script"},"The picture shows a special effect shader I created using this method. With this ShaderGUIEditor, it is easy to divide the shader into different functional areas. And when the segmentation function is not initially used, all are hidden，The Shader code also automatically skips subsequent calculations and only expands when selected for use.":{"zh":"图中是我用该方法制作的特效Shader。借助自定义编辑器，可以清晰划分不同功能区域。未启用的功能默认隐藏，Shader代码也会跳过相关计算，勾选后才展开对应参数。","en":"The picture shows a special effect shader I created using this method. With this ShaderGUIEditor, it is easy to divide the shader into different functional areas. And when the segmentation function is not initially used, all are hidden，The Shader code also automatically skips subsequent calculations and only expands when selected for use."},"Implementation: Built a custom Editor Window":{"zh":"实现：自定义编辑器窗口","en":"Implementation: Built a custom Editor Window"},"Enable Function":{"zh":"启用功能","en":"Enable Function"},"Rendering Breakdown & Reflection":{"zh":"渲染合成与复盘","en":"Rendering Breakdown & Reflection"},"Scene rendering and synthesis":{"zh":"场景渲染与合成","en":"Scene rendering and synthesis"},"Summary":{"zh":"总结","en":"Summary"},"PBR basic coloring":{"zh":"PBR 基础着色","en":"PBR basic coloring"},"Feedback":{"zh":"反馈","en":"Feedback"},"Direct specular reflection of light":{"zh":"直接镜面反射","en":"Direct specular reflection of light"},"Indirect specular reflection of light":{"zh":"间接镜面反射","en":"Indirect specular reflection of light"},"Direct diffuse reflection of light":{"zh":"直接漫反射","en":"Direct diffuse reflection of light"},"When I started this project, my focus was learning HLSL—with the goal of pushing my skill boundaries. The real challenge lay in making shaders and scenes fully compatible, and debugging to resolve issues:For example, when adding refraction effects to semi-transparent water, I encountered over-dark screen colors; but I could only read the opaque object color (not transparent ones) via the RenderTexture tool. To solve this, I debugged step-by-step through the Shader code and found a solution. Second, I designed the Shader with a modular logic (since development teams rarely use simple statements to handle complex rendering). This let the Shader adapt to multiple scenarios, but I did not do enough performance optimization for this realistic-style scene. Next time, I will definitely use strategies like Level of Detail (LOD) and batch optimization.":{"zh":"项目开始时，我希望通过学习 HLSL 拓展自己的能力。真正的挑战是让Shader与场景完整适配，并逐步排查问题。例如，为半透明水面加入折射后，屏幕颜色过暗；同时，渲染纹理只能读取不透明物体的颜色。我通过逐步调试Shader代码找到了处理方法。\n其次，考虑到团队开发通常需要处理复杂的渲染逻辑，我采用模块化结构，让Shader适配不同场景。但这个写实场景的性能优化仍不充分，后续需要更多运用细节层级与批处理等优化策略。","en":"When I started this project, my focus was learning HLSL—with the goal of pushing my skill boundaries. The real challenge lay in making shaders and scenes fully compatible, and debugging to resolve issues:For example, when adding refraction effects to semi-transparent water, I encountered over-dark screen colors; but I could only read the opaque object color (not transparent ones) via the RenderTexture tool. To solve this, I debugged step-by-step through the Shader code and found a solution.\r\nSecond, I designed the Shader with a modular logic (since development teams rarely use simple statements to handle complex rendering). This let the Shader adapt to multiple scenarios, but I did not do enough performance optimization for this realistic-style scene. Next time, I will definitely use strategies like Level of Detail (LOD) and batch optimization."},"Indirect diffuse light reflection":{"zh":"间接漫反射","en":"Indirect diffuse light reflection"},"Indirect diffuse light * BakedGI":{"zh":"间接漫反射 × 烘焙全局光照","en":"Indirect diffuse light * BakedGI"},"After synthesizing the four PBR items above":{"zh":"合成以上四项 PBR 分量后","en":"After synthesizing the four PBR items above"},"Add volume light/fog (Raymarching)":{"zh":"添加体积光与体积雾：光线步进","en":"Add volume light/fog (Raymarching)"},"Post processing (ACES+Bloom+Color Adjust)":{"zh":"后期处理：ACES 色调映射、泛光与颜色调整","en":"Post processing (ACES+Bloom+Color Adjust)"},"SSAO adds shadow masking effect to give the scene a sense of depth":{"zh":"使用屏幕空间环境光遮蔽增强阴影和场景纵深。","en":"SSAO adds shadow masking effect to give the scene a sense of depth"},"Synthesis":{"zh":"合成","en":"Synthesis"},"Team Pojrect. A team of 7 members. Engine: Unity URP Pipeline Responsibilities: Technical Artist / Project Management":{"zh":"团队项目，共 7 人。\n引擎：Unity URP 渲染管线\n职责：技术美术／项目管理","en":"Team Pojrect.  A team of 7 members.\nEngine: Unity URP Pipeline                    \nResponsibilities: Technical Artist / Project Management"},"A narrative-driven platformer puzzle game set in the Chinese underworld. Players take on the role of a mortal who made a pact with a demon—venturing into the underworld to rescue their deceased loved one, while mastering soul-body shifting. Centered on \"Chinese underworld\" aesthetics, the game features a dark crimson netherworld with Buddhist/Taoist symbols, using Red Spider Lily (Lycoris radiata) and the Bridge of Helplessness as core narrative motifs. Navigate perilous environments via key mechanics: astral projection, ghost flame manipulation, and Yin-Yang formation puzzles—all against striking light-shadow contrast":{"zh":"一款以中国冥界为背景、由叙事驱动的平台解谜游戏。玩家扮演与恶魔达成契约的凡人，前往冥界拯救逝去的爱人，并掌握灵魂与肉身切换的能力。\n游戏围绕中国冥界美学展开，以暗红色冥土及佛道符号构建世界，将彼岸花和奈何桥作为核心叙事意象。玩家通过灵魂出窍、操纵鬼火和阴阳阵法解谜穿越险境，体验鲜明的明暗对比。","en":"A narrative-driven platformer puzzle game set in the Chinese underworld. Players take on the role of a mortal who made a pact with a demon—venturing into the underworld to rescue their deceased loved one, while mastering soul-body shifting.\nCentered on \"Chinese underworld\" aesthetics, the game features a dark crimson netherworld with Buddhist/Taoist symbols, using Red Spider Lily (Lycoris radiata) and the Bridge of Helplessness as core narrative motifs. Navigate perilous environments via key mechanics: astral projection, ghost flame manipulation, and Yin-Yang formation puzzles—all against striking light-shadow contrast"},"Lycoris":{"en":"Lycoris","zh":"彼岸花"},"One special point is that we learned to make a trailer for this special game, during which we mastered the use of Timeline and Cinematic Events to handle camera events skillfully—and the whole process and the final effect were truly amazing!":{"zh":"项目中还有一项特别的尝试：为游戏制作预告片。过程中我们学习了时间轴与电影化事件，熟练处理镜头事件，制作过程和最终效果都令人印象深刻。","en":"One special point is that we learned to make a trailer for this special game, during which we mastered the use of Timeline and Cinematic Events to handle camera events skillfully—and the whole process and the final effect were truly amazing!"},"Trailer：https://www.youtube.com/watch?v=Gen78RAZ3zE":{"zh":"预告片：https://www.youtube.com/watch?v=Gen78RAZ3zE","en":"Trailer：https://www.youtube.com/watch?v=Gen78RAZ3zE"},"Concept":{"zh":"概念","en":"Concept"},"Experience and Gameplay":{"zh":"体验与玩法","en":"Experience and Gameplay"},"The player takes on the role of someone who made a deal with a demon and gained the ability to shift between soul and body. He then ventures into the underworld to rescue his deceased wife. The deeper he goes, the more he realizes he is gradually turning into a soul—and that abandoning his physical form is the only way to stay with her. The character can astrally project his soul, inheriting the body's momentum while becoming lighter and gaining the ability to interact with supernatural beings. Players use this ability to solve puzzles.":{"zh":"玩家扮演与恶魔交易后获得灵肉切换能力的人，前往冥界拯救亡妻。随着深入，他逐渐化为灵魂，并发现只有放弃肉身才能与妻子相伴。角色可以让灵魂离开身体，继承肉身的动量，同时变得更轻，并能与超自然事物互动。玩家利用这一能力解开谜题。","en":"The player takes on the role of someone who made a deal with a demon and gained the ability to shift between soul and body. He then ventures into the underworld to rescue his deceased wife. The deeper he goes, the more he realizes he is gradually turning into a soul—and that abandoning his physical form is the only way to stay with her. The character can astrally project his soul, inheriting the body's momentum while becoming lighter and gaining the ability to interact with supernatural beings. Players use this ability to solve puzzles."},"Body carrying a soul: Heavy + Basic movement + Can be regenerated by the soul.":{"zh":"承载灵魂的肉身：\n沉重，具备基本移动能力，\n可由灵魂重新生成。","en":"Body carrying a soul: \nHeavy +  Basic movement +\nCan be regenerated by the soul."},"Soul: Lightweight + Incorporea + Capable of interacting with ghostly flames.":{"zh":"灵魂：\n轻盈、无实体，\n能够与鬼火互动。","en":"Soul: \nLightweight + Incorporea + Capable of interacting with ghostly flames."},"Body without a soul: Heavy + Immobile + Auto destroyed when Regenerated":{"zh":"失去灵魂的肉身：\n沉重、无法移动，\n重新生成肉身时会自动销毁。","en":"Body without a soul:\n Heavy + Immobile + \nAuto destroyed when Regenerated"},"Game pillar":{"zh":"核心玩法支柱","en":"Game pillar"},"Story background":{"zh":"故事背景","en":"Story background"},"A man awakens in the underworld to find he possesses a new ability: his soul can leave his body. By repeatedly projecting his soul and leaping from his physical form, he traverses the treacherous terrain of hell. This power offers him a chance to bring his wife back from the depths of the underworld.":{"zh":"一名男子在冥界醒来，发现自己获得了灵魂出窍的能力。他反复让灵魂跃出肉身，穿过地狱险峻的地形。这种力量让他看到了从冥界深处带回妻子的机会。","en":"A man awakens in the underworld to find he possesses a new ability: his soul can leave his body. By repeatedly projecting his soul and leaping from his physical form, he traverses the treacherous terrain of hell. This power offers him a chance to bring his wife back from the depths of the underworld."},"He arrives at a field brimming with Lycoris , which stir memories of the joyful times he shared with his wife. Suddenly, the flowers transform into ghostly flames, searing his hands. Though he loses his physical hands, his soul grows significantly stronger.":{"zh":"他来到开满彼岸花的花田，想起与妻子相伴的幸福时光。花朵突然化为鬼火，烧灼他的双手。虽然失去了肉身的双手，灵魂却变得更加强大。","en":"He arrives at a field brimming with Lycoris , which stir memories of the joyful times he shared with his wife. Suddenly, the flowers transform into ghostly flames, searing his hands. Though he loses his physical hands, his soul grows significantly stronger."},"He presses on with his adventure, harnessing the power that resonates with the ghostly flames to unlock mechanisms. As a soul, he grows increasingly powerful. Finally, he finds his wife—but only a soul may pass forward, meaning he must abandon his physical form to be with her. So he resolutely casts his body aside and continues walking toward her.":{"zh":"他继续冒险，利用与鬼火共鸣的力量开启机关，灵魂也不断增强。最终，他找到了妻子，但前方只有灵魂能够通过。他必须放弃肉身才能相伴，于是毅然舍弃身体，向她走去。","en":"He presses on with his adventure, harnessing the power that resonates with the ghostly flames to unlock mechanisms. As a soul, he grows increasingly powerful. Finally, he finds his wife—but only a soul may pass forward, meaning he must abandon his physical form to be with her. So he resolutely casts his body aside and continues walking toward her."},"Producing Process":{"zh":"制作流程","en":"Producing Process"},"Prototype ——> Muture Levels":{"zh":"原型 → 完整关卡","en":"Prototype ——> Muture Levels"},"Project Management":{"zh":"项目管理","en":"Project Management"},"The overall gameplay perspective, lighting, and rendering style of the game are inspired by Inside.":{"zh":"游戏的整体玩法视角、灯光和渲染风格参考了《深入》。","en":"The overall gameplay perspective, lighting, and rendering style of the game are inspired by Inside."},"I also served as the project manager for this project, utilizing Tower for team management.":{"zh":"我同时担任项目经理，使用 Tower 进行团队管理。","en":"I also served as the project manager for this project, utilizing Tower for team management."},"We adopt a branch-based approach for production. The Gameplay programmers and the lead planner independently verify the 3C and develop the game prototype in the Design branch.":{"zh":"我们采用分支协作方式制作。玩法程序和主策划在设计分支中独立验证角色、摄像机与操控，并开发游戏原型。","en":"We adopt a branch-based approach for production. The Gameplay programmers and the lead planner independently verify the 3C and develop the game prototype in the Design branch."},"Production & Project Management":{"zh":"制作流程与项目管理","en":"Production & Project Management"},"Soul power":{"zh":"灵魂能力","en":"Soul power"},"Jump":{"zh":"跳跃","en":"Jump"},"Soul/Body":{"zh":"灵魂／肉身","en":"Soul/Body"},"movement":{"zh":"移动","en":"movement"},"My responsibilities included conducting weekly team meetings to track progress, reporting updates to the instructor, documenting meeting notes to gather feedback, facilitating follow-up discussions to explore improvement strategies, and continuously adjusting plans based on the team members' productivity.":{"zh":"我的职责包括每周组织团队会议、跟踪进度、向导师汇报、记录会议与反馈，并推动后续讨论与改进，同时根据成员的产出持续调整计划。","en":"My responsibilities included conducting weekly team meetings to track progress, reporting updates to the instructor, documenting meeting notes to gather feedback, facilitating follow-up discussions to explore improvement strategies, and continuously adjusting plans based on the team members' productivity."},"The designer created the basic layout of the level using whiteboxes to represent collision areas.":{"zh":"设计师先用白盒表示碰撞区域，搭建关卡的基础布局。","en":"The designer created the basic layout of the level using whiteboxes to represent collision areas."},"I independently utilized assets to construct an art scene complete with lighting effects. Once he finalized the level modifications, I merged the art assets with the whiteboxes in accordance with scene art standards.":{"zh":"我独立使用资产搭建带有灯光效果的美术场景。关卡修改确定后，再按照场景美术标准，将美术资产与白盒合并。","en":"I independently utilized assets to construct an art scene complete with lighting effects. Once he finalized the level modifications, I merged the art assets with the whiteboxes in accordance with scene art standards."},"Scene Art":{"zh":"场景美术","en":"Scene Art"},"Visual reference":{"zh":"视觉参考","en":"Visual reference"},"For the visual aspects, we drew inspiration from the Chinese conceptualization of the underworld. The game begins at the edge of hell and progresses all the way to the Gate of the Underworld. My environmental art work focused on the first part, where I created a world composed of stone and lava.":{"zh":"视觉表现参考了中国对冥界的想象。游戏从地狱边缘开始，一路推进到冥界大门。我负责前半段环境美术，构建由岩石与熔岩组成的世界。","en":"For the visual aspects, we drew inspiration from the Chinese conceptualization of the underworld. The game begins at the edge of hell and progresses all the way to the Gate of the Underworld. My environmental art work focused on the first part, where I created a world composed of stone and lava."},"Art Style Direction: A hellscape dominated by dark red tones, with the blue protagonist standing out against the crimson backdrop of the underworld.":{"zh":"美术风格方向：以暗红色为主的地狱景观，让蓝色主角从冥界的深红背景中突出。","en":"Art Style Direction: A hellscape dominated by dark red tones, with the blue protagonist standing out against the crimson backdrop of the underworld."},"Level Art":{"zh":"关卡美术","en":"Level Art"},"Scenario Setting":{"zh":"场景设定","en":"Scenario Setting"},"To achieve a 2D side-scrolling effect, we set FOV 10. We placed objects far apart, arranged art assets in layers separated by volumetric fog, used different directional lights for each scene section, and applied Depth of Field and Box post-processing to adjust colors and mood. Thus we could create varied atmospheres in one scene":{"zh":"为实现二维横版效果，我们将视场角设为 10，将物体拉开距离，利用体积雾分隔不同资产层，为各区域设置独立平行光，再通过景深与盒体后处理调节色彩和情绪，从而在同一场景中营造多种氛围。","en":"To achieve a 2D side-scrolling effect, we set FOV 10. We placed objects far apart, arranged art assets in layers separated by volumetric fog, used different directional lights for each scene section, and applied Depth of Field and Box post-processing to adjust colors and mood. Thus we could create varied atmospheres in one scene"},"Game starts":{"zh":"游戏开始","en":"Game starts"},"Cave":{"zh":"洞穴","en":"Cave"},"Ruins":{"zh":"遗迹","en":"Ruins"},"Gate of Hell":{"zh":"地狱之门","en":"Gate of Hell"},"I used different directional lights for each section of the scene—key light, fill light, and platform accent light—to visually separate them.":{"zh":"我为各段场景分别设置主光、补光和平台强调光，在视觉上区分不同区域。","en":"I used different directional lights for each section of the scene—key light, fill light, and platform accent light—to visually separate them."},"Project iteration started from 2026":{"zh":"2026 年开始的项目迭代","en":"Project iteration started from 2026"},"After interning as a TA, when I looked back at this project, I found there were many areas that could be iterated on. I believe the environment should feel more abstract rather than literal; instead of balanced lighting, we should emphasize stronger light and shadow contrasts.":{"zh":"在技术美术实习后回看这个项目，我发现还有许多可以改进之处。\n我认为环境应当更抽象，而非直接再现现实；灯光不必均衡，应当强调更强烈的明暗对比。","en":"After interning as a TA, when I looked back at this project, I found there were many areas that could be iterated on.\nI believe the environment should feel more abstract rather than literal; instead of balanced lighting, we should emphasize stronger light and shadow contrasts."},"Scene Art & Iteration":{"zh":"场景美术与迭代","en":"Scene Art & Iteration"},"New Rules I set:":{"zh":"我制定的新规则：","en":"New Rules I set:"},"All shaders must avoid realistic textures, using more stylized patterns. A HeroLight is used to setup the player character; Corresponding lights should be added at all self-illuminating scene areas, in order to highlight characters and enhance danger.":{"zh":"所有Shader避免使用写实纹理，改用更风格化的图案。\n使用角色专属灯光塑造玩家角色。\n所有场景自发光区域都加入相应光源，用于突出角色并增强危险感。","en":"All shaders must avoid realistic textures, using more stylized patterns.\nA HeroLight is used to setup the player character; \nCorresponding lights should be added at all self-illuminating scene areas, in order to highlight characters and enhance danger."},"Character":{"en":"Character","zh":"角色"},"Iterative Rendering":{"zh":"渲染迭代","en":"Iterative Rendering"},"Character Design":{"zh":"角色设计","en":"Character Design"},"After studying shader techniques and revisiting the rendering approach of Inside, I realized that the previous character design required a major overhaul.":{"zh":"学习Shader技术并重新研究《深入》的渲染方式后，我意识到原先的角色设计需要大幅调整。","en":"After studying shader techniques and revisiting the rendering approach of Inside, I realized that the previous character design required a major overhaul."},"Our art direction envisions the protagonist as a slender, introverted young man, whose identity is defined by his daily habit of wearing a hoodie. His modern attire creates a striking contrast when he enters the discordant realm of hell. Nevertheless, his animations will emphasize his unwavering determination to save his wife.":{"zh":"美术设定中的主角是一名瘦削、内向的年轻人，习惯穿连帽衫。现代服饰与不协调的地狱环境形成鲜明对比，而动画则着重表现他拯救妻子的坚定决心。","en":"Our art direction envisions the protagonist as a slender, introverted young man, whose identity is defined by his daily habit of wearing a hoodie. His modern attire creates a striking contrast when he enters the discordant realm of hell. Nevertheless, his animations will emphasize his unwavering determination to save his wife."},"Character Art & Animation":{"zh":"角色美术与动画","en":"Character Art & Animation"},"I used Mixamo for character rigging, adjusted the animations, and wrote code to integrate them with the character mechanics programmed by the lead developer.":{"zh":"我使用 Mixamo 完成角色绑定，调整动画，并编写代码，将动画与主程序制作的角色机制整合。","en":"I used Mixamo for character rigging, adjusted the animations, and wrote code to integrate them with the character mechanics programmed by the lead developer."},"Black/white mask to offset/push/pull shadow edges via displacement.Enforce clean, stylized shadows even with imperfect topology.":{"zh":"通过黑白遮罩和位移，偏移、推动或收缩阴影边缘，即使拓扑不够理想，也能保持干净、风格化的阴影。","en":"Black/white mask to offset/push/pull shadow edges via displacement.Enforce clean, stylized shadows even with imperfect topology."},"Between the first and second levels, the character's hands are burned by the Red Spider Lilies. Consequently, two models and four animation controllers are required. I also utilized a dissolve shader to express the transition between the body and the soul.":{"zh":"第一关与第二关之间，角色的双手被彼岸花烧毁，因此需要两套模型和四个动画控制器。我还使用溶解Shader表现肉身与灵魂之间的转换。","en":"Between the first and second levels, the character's hands are burned by the Red Spider Lilies. Consequently, two models and four animation controllers are required. I also utilized a dissolve shader to express the transition between the body and the soul."},"C# Ramp generator for real-time gradient tweaking & preview on character.Light gray → deep blue ramp for customizable light/shadow transition.":{"zh":"使用 C# 制作渐变生成器，实时调整并预览角色上的渐变。\n从浅灰到深蓝的渐变用于自定义明暗过渡。","en":"C# Ramp generator for real-time gradient tweaking & preview on character.Light gray \n→ deep blue ramp for customizable light/shadow transition."},"Blinn-Phong base + Threshold/Softness, clipped with SmoothStep.Highlights only on key objects: sharp, high-contrast, distinct shape.":{"zh":"基于 Blinn–Phong 模型，结合阈值与柔和度，并通过平滑阶跃函数裁切。高光仅用于关键物体，保持锐利、对比鲜明且形状清晰。","en":"Blinn-Phong base + Threshold/Softness, clipped with SmoothStep.Highlights only on key objects: sharp, high-contrast, distinct shape."},"Gameplay VFX":{"zh":"玩法特效","en":"Gameplay VFX"},"Yin Yang Plate":{"zh":"阴阳盘","en":"Yin Yang Plate"},"Blood Pipeline":{"zh":"血液管道","en":"Blood Pipeline"},"Each formation requires the absorption of both life and death energy. The character must keep his body on the Yang platform while guiding his soul to the Yin platform to activate this mechanism.":{"zh":"每个阵法都需要吸收生与死的能量。角色必须让肉身留在阳台上，同时引导灵魂前往阴台，才能激活机关。","en":"Each formation requires the absorption of both life and death energy. The character must keep his body on the Yang platform while guiding his soul to the Yin platform to activate this mechanism."},"This is a sacrificial platter. When the player steps on the flesh, blood is squeezed out and flows through the pipes. Only when the blood travels through all the pipes to the gate can it channel the power to open it. Sometimes the pipes are blocked by talisman papers, and the player must first use their soul to absorb the power of ghost fire to break the seal.":{"zh":"这是一个祭祀托盘。玩家踩上血肉后，血液会被挤出并沿管道流动。只有血液流经全部管道抵达大门，才能将力量传递给门并将其打开。\n有些管道被符纸封住，玩家需要先让灵魂吸收鬼火力量，打破封印。","en":"This is a sacrificial platter. When the player steps on the flesh, blood is squeezed out and flows through the pipes. Only when the blood travels through all the pipes to the gate can it channel the power to open it.\nSometimes the pipes are blocked by talisman papers, and the player must first use their soul to absorb the power of ghost fire to break the seal."},"Floating Text：":{"zh":"漂浮文字：","en":"Floating Text："},"Talisman":{"zh":"符纸","en":"Talisman"},"I only used straight pipes and elbows, and connected them together. I created an effect with ASE to make the flow go from one direction to another. The flow direction is exposed as a parameter named 'Direction', which can be controlled in the script of this pipe group.":{"zh":"我仅使用直管和弯头进行拼接，并通过 ASE 制作让液体沿指定方向流动的效果。流向作为名为 Direction 的参数暴露出来，可由这一组管道的脚本控制。","en":"I only used straight pipes and elbows, and connected them together. I created an effect with ASE to make the flow go from one direction to another. The flow direction\n                           is exposed as a parameter \n                           named 'Direction', which can\n                          be controlled in the script of\n                            this pipe group."},"Talisman Die Out ——> Dissolve Shader with Burn Ramp":{"zh":"符纸消失 → 带有燃烧渐变的溶解Shader","en":"Talisman Die Out ——> Dissolve Shader with Burn Ramp"},"Interactable Ghost Fire":{"zh":"可交互鬼火","en":"Interactable Ghost Fire"},"In Level 2, the character’s soul can resonate with ghost fire to overcome numerous obstacles.":{"zh":"第二关中，角色的灵魂可以与鬼火共鸣，克服各种障碍。","en":"In Level 2, the character’s soul can resonate with ghost fire to overcome numerous obstacles."},"I created the basic flame using the Particle System and Shader Graph. Subsequently, I utilized the Trail module and the Force Over Lifetime parameter of the Particle System to control the direction of the flame's tail, giving it a pulled and stretched visual effect.":{"zh":"我使用粒子系统与 Shader Graph 制作基础火焰，再通过拖尾模块和生命周期力参数控制焰尾方向，呈现被牵引、拉伸的视觉效果。","en":"I created the basic flame using the Particle System and Shader Graph.  \nSubsequently, I utilized the Trail module and the Force Over Lifetime parameter of the Particle System to control the direction of the flame's tail, giving it a pulled and stretched visual effect."},"After extensive testing, I opted to use trigonometric functions to calculate the flame's end variations. The game features three distinct ghost flame mechanics.":{"zh":"经过大量测试，我选择使用三角函数计算火焰末端的变化。游戏中设计了三种不同的鬼火机制。","en":"After extensive testing, I opted to use trigonometric functions to calculate the flame's end variations. The game features three distinct ghost flame mechanics."},"Ghost Fire on Box":{"zh":"箱子上的鬼火","en":"Ghost Fire on Box"},"Ghost Fire on Spell":{"zh":"符咒上的鬼火","en":"Ghost Fire on Spell"},"Individual Ghost Fire":{"zh":"独立鬼火","en":"Individual Ghost Fire"},"resonate with the fire to burn talisman":{"zh":"与鬼火共鸣，燃烧符纸","en":"resonate with the fire \nto burn talisman"},"resonate with the fire to pull the cage":{"zh":"与鬼火共鸣，拉动笼子","en":"resonate with the fire \nto pull the cage"},"resonate with the fire to pull oneself":{"zh":"与鬼火共鸣，牵引自身","en":"resonate with the fire \nto pull oneself"},"Indie Monsters - Clock Eye":{"zh":"独立怪物设计：时钟眼球","en":"Indie Monsters - Clock Eye"},"Minigames I designed and implemented":{"zh":"我设计并实现的小游戏","en":"Minigames I designed and implemented"},"Indie Monster · Clock Eye":{"zh":"独立怪物：时钟眼球","en":"Indie Monster · Clock Eye"},"Indie Monsters - Shadow Man":{"en":"Indie Monsters - Shadow Man","zh":"独立怪物设计：暗影人"},"我自己小时候的想法：":{"zh":"我自己小时候的想法：","en":"An idea from my childhood:"},"概念：":{"zh":"概念：","en":"Concept:"},"Body carrying a soul: Heavy, capable of basic movement, can be regenerated by the soul.":{"zh":"承载灵魂的肉身：沉重，具备基本移动能力，可由灵魂重新生成。","en":"Body carrying a soul: Heavy, capable of basic movement, can be regenerated by the soul."},"Soul: Lightweight, incorporeal, capable of interacting with ghostly flames.":{"zh":"灵魂：轻盈、无实体，能够与鬼火互动。","en":"Soul: Lightweight, incorporeal, capable of interacting with ghostly flames."},"Body without a soul: Heavy, immobile, can be destroyed.":{"zh":"失去灵魂的肉身：沉重、无法移动，可以被销毁。","en":"Body without a soul: Heavy, immobile, can be destroyed."},"箭头————>表示迭代":{"zh":"箭头表示迭代方向","en":"Arrows indicate the direction of iteration."},"A man awakens in the underworld to find he possesses a new ability his soul can leave his body. By repeatedly projecting his soul and leaping from his physical form, he traverses the treacherous terrain of hell. This power offers him a chance to bring his wife back from the depths of the underworld.":{"zh":"一名男子在冥界醒来，发现自己获得了灵魂出窍的能力。他反复让灵魂跃出肉身，穿过地狱险峻的地形。这种力量让他看到了从冥界深处带回妻子的机会。","en":"A man awakens in the underworld to find he possesses a new ability his soul can leave his body. By repeatedly projecting his soul and leaping from his physical form, he traverses the treacherous terrain of hell. This power offers him a chance to bring his wife back from the depths of the underworld."},"He arrives at a field brimming with Red Spider Lilies, which stir memories of the joyful times he shared with his wife. Suddenly, the flowers transform into ghostly flames, searing his hands. Though he loses his physical hands, his soul grows significantly stronger.":{"zh":"他来到开满彼岸花的花田，想起与妻子相伴的幸福时光。花朵突然化为鬼火，烧灼他的双手。虽然失去了肉身的双手，灵魂却变得更加强大。","en":"He arrives at a field brimming with Red Spider Lilies, which stir memories of the joyful times he shared with his wife. Suddenly, the flowers transform into ghostly flames, searing his hands. Though he loses his physical hands, his soul grows significantly stronger."},"迭代：原本的在VR环境中因为过于潦草而显得不那么恐怖，思考过荒诞风格的做法，但尝试了以后还是不吓人。我认为可能要在VR中起到效果，还是要做的写实一些。":{"zh":"迭代：原先的效果在虚拟现实环境中过于潦草，恐怖感不足。我尝试过荒诞风格，但仍然不够吓人。因此，我认为需要更写实的表现，才能在虚拟现实中达到预期效果。","en":"Iteration: The original effect felt too rough to be frightening in VR. I explored an absurdist style, but the result still lacked impact. I concluded that a more realistic approach would work better in VR."},"迭代：我使用写实人物模型+Noise做出了电视花屏且浮空的感觉 同时在周围做了个Mask，用GrabScreenColor+Distortion使人物边缘扰动、模糊。 由于GrabScreenColor只能Grab到Opaque的Object，所以我人物本身的材质使用了Dither来做半透明效果。":{"zh":"迭代：使用写实人物模型和噪声，营造电视花屏与悬浮的感觉。\n同时在周围添加遮罩，通过屏幕颜色采样与扭曲，让人物边缘产生扰动和模糊。\n由于屏幕颜色只能采样不透明物体，人物材质使用抖动实现半透明效果。","en":"Iteration: I combined a realistic character model with noise to create a floating figure with TV-static interference.\nI added a surrounding mask and used screen-color sampling with distortion to blur and disturb the character's edges.\nBecause screen-color sampling captures only opaque objects, the character material uses dithering to achieve a translucent appearance."},"This project draws inspiration from the \"Laputa's cabin\" in Hayao Miyazaki's Castle in the Sky. I translated 2D hand-painted aesthetics into a real-time 3D rendered environment while exploring the full-cycle technical implementation of Procedural Content Generation (PCG). Using Substance Designer, I developed 3 material maps based on the original art. Additionally, with Houdini, I created parametric tools that enable one-click generation of stylized brick walls, spline-based stone wall creation, and layered mountain terrain via HeightField systems—greatly accelerating the efficiency of scene iteration. Within Unreal Engine 5, I applied custom Toon Shaders, vertex-color materials, and Runtime Virtual Texturing (RVT) techniques to enhance the simplicity of colors and the abstraction of lighting, thus recreating Studio Ghibli's distinctive soft visual style.":{"zh":"项目以宫崎骏《天空之城》中拉普达的小屋为参考，将二维手绘美学转化为实时三维场景，并探索程序化内容生成的完整技术流程。\n我使用 Substance Designer 根据原画制作三种材质贴图，并在 Houdini 中开发参数化工具，实现风格化砖墙一键生成、样条石墙制作，以及基于高度场的分层山地地形，提升场景迭代效率。\n在虚幻引擎 5 中，我结合自定义卡通Shader、顶点色材质和运行时虚拟纹理，简化色彩与光照表现，重现吉卜力柔和的视觉风格。","en":"This project draws inspiration from the \"Laputa's cabin\" in Hayao Miyazaki's Castle in the Sky. I translated 2D hand-painted aesthetics into a real-time 3D rendered environment while exploring the full-cycle technical implementation of Procedural Content Generation (PCG).\nUsing Substance Designer, I developed 3 material maps based on the original art. Additionally, with Houdini, I created parametric tools that enable one-click generation of stylized brick walls, spline-based stone wall creation, and layered mountain terrain via HeightField systems—greatly accelerating the efficiency of scene iteration.\nWithin Unreal Engine 5, I applied custom Toon Shaders, vertex-color materials, and Runtime Virtual Texturing (RVT) techniques to enhance the simplicity of colors and the abstraction of lighting, thus recreating Studio Ghibli's distinctive soft visual style."},"Laputa":{"zh":"天空之城","en":"Laputa"},"Stylized Material":{"zh":"风格化材质","en":"Stylized Material"},"Brick Wall Material":{"zh":"砖墙材质","en":"Brick Wall Material"},"Slope Blue Edge Wear + Flood Fill + Curvature Edge Highlights":{"zh":"斜率模糊边缘磨损、泛洪填充与曲率边缘高光","en":"Slope Blue Edge Wear + Flood Fill + Curvature Edge Highlights"},"Eaves Material":{"zh":"屋檐材质","en":"Eaves Material"},"Tile Sampler + Flood Fil":{"zh":"平铺采样器与泛洪填充","en":"Tile Sampler + Flood Fil"},"Inspiration & Procedural Materials":{"zh":"风格化程序材质","en":"Inspiration & Procedural Materials"},"Wooden Plank Wall Material":{"zh":"木板墙材质","en":"Wooden Plank Wall Material"},"Directional Warp Grain Generation + Tile Generator + Height-Based Moss Mask":{"zh":"方向扭曲木纹、平铺生成器与基于高度的苔藓遮罩","en":"Directional Warp Grain Generation + Tile Generator + Height-Based Moss Mask"},"Finally, I added a few brushstroke touches to enhance the stylized feel—a technique I carried over from experience on another game project.":{"zh":"最后，我添加了少量笔触来增强风格化质感，这一方法来自另一个游戏项目的制作经验。","en":"Finally, I added a few brushstroke touches to enhance the stylized feel—a technique I carried over from experience on another game project."},"Houdini Procedural Assets":{"zh":"Houdini 程序化资产","en":"Houdini Procedural Assets"},"House Brick Wall":{"zh":"房屋砖墙","en":"House Brick Wall"},"Production Process":{"zh":"制作流程","en":"Production Process"},"Procedural Feature: Users only need to place two cubes—one to generate a brick wall based on Cube 1's transform, and another to create a door based on Cube 2's transform. When the material texture of the wall is modified, the wall model updates accordingly.It streamlines the workflow by eliminating the need for manual modeling of complex brick walls. Parameters: Adjust Bricks: Brick Tile Scale, Brick Height. Adjust Door: Has Door, Door Bevel Distance, Door Bevel Division, Door Width. Adjust Top Edge: Top Edge Width, Top Edge Scale.":{"zh":"程序化功能：用户只需放置两个立方体，一个依据自身变换生成砖墙，另一个依据自身变换生成门。修改墙体材质纹理后，模型也会同步更新，无须手工搭建复杂砖墙。\n砖块参数：平铺比例与砖块高度。\n门参数：是否生成门、倒角距离、倒角分段与门宽。\n顶边参数：宽度与缩放。","en":"Procedural Feature: Users only need to place two cubes—one to generate a brick wall based on Cube 1's transform, and another to create a door based on Cube 2's transform. When the material texture of the wall is modified, the wall model updates accordingly.It streamlines the workflow by eliminating the need for manual modeling of complex brick walls. Parameters:  Adjust Bricks: Brick Tile Scale, Brick Height.  Adjust Door: Has Door, Door Bevel Distance, Door Bevel Division, Door Width.  Adjust Top Edge: Top Edge Width, Top Edge Scale."},"I used the brick material created in Substance Designer, then converted it into a model mesh by applying Attribute from Map and Poly Reduce.":{"zh":"我使用在 Substance Designer 中制作的砖块材质，再通过从贴图读取属性与多边形减面节点，将它转为模型网格。","en":"I used the brick material created in Substance Designer, then converted it into a model mesh by applying Attribute from Map and Poly Reduce."},"Houdini Procedural Brick Walls":{"zh":"Houdini 程序化砖墙","en":"Houdini Procedural Brick Walls"},"Preview Mode Set I separated performance‑intensive nodes using a Switch, allowing users to adjust parameters in Preview Mode first, then toggle the FinalResult button to view the final outcome.":{"zh":"预览模式设置：\n我通过切换节点隔离开销较大的节点，让用户先在预览模式中调整参数，再切换到最终结果查看完整模型。","en":"Preview Mode Set\nI separated performance‑intensive nodes using a Switch, allowing users to adjust parameters in Preview Mode first, then toggle the FinalResult button \nto view the final outcome."},"Using House Brick Walls in Unreal Engine":{"zh":"在虚幻引擎中使用房屋砖墙","en":"Using House Brick Walls in Unreal Engine"},"Debugging Position and Shape in Preview Mode":{"zh":"在预览模式中调试位置与形状","en":"Debugging Position and Shape in Preview Mode"},"Click Is Final Result to generate the actual model.":{"zh":"勾选最终结果，生成实际模型。","en":"Click Is Final Result to generate the actual model."},"Advanced Workflow: I used Blast to extract specific faces of a cube, Boolean to cut out the door opening, and finally Sweep to generate the door frame, top trim, and related structural details.":{"zh":"进阶流程：\n使用删除节点提取立方体的指定面，再通过布尔运算切出门洞，最后使用扫掠生成门框、顶部饰边及其他结构细节。","en":"Advanced Workflow: \nI used Blast to extract specific faces of a cube, Boolean to cut out the door opening, and finally Sweep to generate the door frame, top trim, and related structural details."},"Foreground Stone Wall":{"zh":"前景石墙","en":"Foreground Stone Wall"},"Parameters: The wall's overall length, width, and height can be adjusted, along with the individual stone's length, width, height, and the degree of weathering or breakage.":{"zh":"参数：可调节墙体整体长宽高，以及单块石头的长宽高和风化、破损程度。","en":"Parameters: The wall's overall length, width, and height can be adjusted, along with the individual stone's length, width, height, and the degree of weathering or breakage."},"Use For Loop to modify parameters for each stone.":{"zh":"使用循环逐块修改石头的参数。","en":"Use For Loop to modify parameters for each stone."},"Procedural Stone Walls & Mountains":{"zh":"程序化石墙与山体","en":"Procedural Stone Walls & Mountains"},"Key Node: Using Point Wrangle to script a pattern: modify the point positions of odd‑numbered primitives based on the vector between adjacent points and a given length, then add extra points and polylines. This enables staggered placement of stones.":{"zh":"关键节点：在点处理节点中编写脚本，根据相邻点之间的向量和给定长度，修改奇数编号图元的点位置，并添加额外的点和折线，从而实现石块的错缝排列。","en":"Key Node:  Using Point Wrangle to script a pattern: modify the point positions of odd‑numbered primitives based on the vector between adjacent points and a given length, then add extra points and polylines.  \nThis enables staggered placement of stones."},"Using Foreground Stone Walls in Unreal Engine":{"zh":"在虚幻引擎中使用前景石墙","en":"Using Foreground Stone Walls in Unreal Engine"},"Drag/Adjust Spline":{"zh":"拖动／调整样条","en":"Drag/Adjust Spline"},"Adjust the desired effects in Preview Mode.":{"zh":"在预览模式中调整到所需效果。","en":"Adjust the desired effects in Preview Mode."},"Background Mountain Range":{"zh":"背景山脉","en":"Background Mountain Range"},"Use various nodes to sculpt the overall form.":{"zh":"使用多种节点塑造整体形态。","en":"Use various nodes to sculpt the overall form."},"The mountain range has been enhanced with a HeightField Erode node.":{"zh":"使用高度场侵蚀节点增强山脉细节。","en":"The mountain range has been enhanced with a HeightField Erode node."},"After applying auto‑coloration to the mountain range.":{"zh":"山脉自动着色后的效果。","en":"After applying auto‑coloration to the mountain range."},"I utilized Sweep combined with Mix by Attribute node to create layered mountain forms and blend terrain at varying elevations, roughly sculpting the shape shown below.":{"zh":"我结合扫掠与按属性混合节点，创建分层山体，并混合不同高度的地形，大致塑造出下图所示形态。","en":"I utilized Sweep combined with Mix by Attribute node to create layered mountain forms and blend terrain at varying elevations, roughly sculpting the shape shown below."},"Thought process: Another attempt involved adding elements like rivers, but it felt too realistic and was ultimately not adopted.":{"zh":"思路：也尝试过加入河流等元素，但效果过于写实，最终没有采用。","en":"Thought process: Another attempt involved adding elements like rivers, but it felt too realistic and was ultimately not adopted."},"Export as a **HeightMap** for use in Unreal Engine.":{"zh":"导出为高度图，供虚幻引擎使用。","en":"Export as a **HeightMap** for use in Unreal Engine."},"Core Models & UE Materials":{"zh":"核心模型与虚幻引擎材质","en":"Core Models & UE Materials"},"Feedback & Iteration":{"zh":"反馈与迭代","en":"Feedback & Iteration"},"Core Asset — Laputa's Cabin":{"zh":"核心资产：拉普达的小屋","en":"Core Asset — Laputa's Cabin"},"Stone Wall - Vertex Color Material":{"zh":"石墙：顶点色材质","en":"Stone Wall - Vertex Color Material"},"After working on it, I realized that stylization mainly involves simplifying details—for example, with a brick wall, only basic embossing or highlights are needed.":{"zh":"制作后我意识到，风格化主要在于简化细节。例如砖墙只需基本的凹凸关系或高光，而不必堆叠复杂纹理。","en":"After working on it, I realized that stylization mainly involves simplifying details—for example, with a brick wall, only basic embossing or highlights are needed."},"I created the house model in Maya, as we plan to utilize materials produced in Substance Designer—only UV unwrapping was required.":{"zh":"我在 Maya 中制作房屋模型。由于计划使用 Substance Designer 制作的材质，模型只需要完成纹理坐标展开。","en":"I created the house model in Maya, as we plan to utilize materials produced in Substance Designer—only UV unwrapping was required."},"Runtime Virtual Texturing (RVT) Grass. This makes the grass blend more naturally with the landscape.":{"zh":"使用运行时虚拟纹理的草地。\n这让草地与地形的衔接更加自然。","en":"Runtime Virtual Texturing (RVT) Grass.\nThis makes the grass blend more naturally with the landscape."},"Stone Wall — Vertex Color Shader":{"zh":"石墙：顶点色Shader","en":"Stone Wall — Vertex Color Shader"},"Scene Construction and Iteration":{"zh":"场景搭建与迭代","en":"Scene Construction and Iteration"},"I studied Substance Designer courses and created brick and wood materials for the house. However, they appear too realistic and do not align with my original reference images.":{"zh":"我学习了 Substance Designer 课程，为房屋制作砖石与木材材质，但它们偏向写实，与最初的参考图风格不一致。","en":"I studied Substance Designer courses and created brick and wood materials for the house. However, they appear too realistic and do not align with my original reference images."},"My Works in":{"zh":"我的项目工作","en":"My Works in"},"Tower Of Fantasy":{"zh":"幻塔","en":"Tower Of Fantasy"},"Work Project in Company UE4 Website：https://giselleli.framer.wiki/workproj/tof Video：https://www.youtube.com/watch?v=M6h2-ChHi1I":{"zh":"公司项目，使用 UE4。\n项目网站：https://giselleli.framer.wiki/workproj/tof\n视频：https://www.youtube.com/watch?v=M6h2-ChHi1I","en":"Work Project in Company UE4\nWebsite：https://giselleli.framer.wiki/workproj/tof\nVideo：https://www.youtube.com/watch?v=M6h2-ChHi1I"},"From 2024 to 2025, I worked as a Level Designer at Tower of Fantasy, where I was responsible for a wealth of gameplay design, visual presentation design and technical implementation. I was mainly involved in the development of Version 5.0, and created a variety of small and large gameplay modes themed on the universe.":{"zh":"2024 至 2025 年，我在《幻塔》担任关卡设计师，负责多种玩法设计、视觉表现设计与技术实现，主要参与 5.0 版本开发，制作了多种以宇宙为主题的大小型玩法。","en":"From 2024 to 2025, I worked as a Level Designer at Tower of Fantasy, where I was responsible for a wealth of gameplay design, visual presentation design and technical implementation. I was mainly involved in the development of Version 5.0, and created a variety of small and large gameplay modes themed on the universe."},"Open World Puzzle Gameplays":{"zh":"开放世界解谜玩法","en":"Open World Puzzle Gameplays"},"The world of Version 5.0 is named \"Kailo\". According to the setting, players need to find a kind of \"Mimic\" and extract its core energy. Based on this setting, I designed the \"Quantum\" Rubik's Cube and the \"Displacement\" Rubik's Cube through color modification.":{"zh":"5.0 版本的世界名为卡洛。根据设定，玩家需要寻找一种拟态生物并提取其核心能量。我据此通过颜色变化，设计了量子魔方与位移魔方两种玩法。","en":"The world of Version 5.0 is named \"Kailo\". According to the setting, players need to find a kind of \"Mimic\" and extract its core energy. Based on this setting, I designed the \"Quantum\" Rubik's Cube and the \"Displacement\" Rubik's Cube through color modification."},"This cube features a quantum lock mechanism similar to that of the Weeping Angels. When not under the player's gaze, it begins to move and teleports randomly onto any physical object.":{"zh":"这一魔方采用类似哭泣天使的量子锁机制：当玩家没有注视它时，它会移动，并随机传送到某个实体物体上。","en":"This cube features a quantum lock mechanism similar to that of the Weeping Angels. When not under the player's gaze, it begins to move and teleports randomly onto any physical object."},"Gameplay Video: https://www.youtube.com/watch?v=M6h2-ChHi1I":{"zh":"玩法视频：https://www.youtube.com/watch?v=M6h2-ChHi1I","en":"Gameplay Video: https://www.youtube.com/watch?v=M6h2-ChHi1I"},"The core of the \"Displaced Mimic\" is in the air at the very beginning and is extremely heavy. Players can move it back by activating the \"Lunar Gravity\" device. After lunar gravity is activated, the player's gravity is drastically reduced, entering Lunar State 3C, and physical feedback is triggered upon collision with surrounding objects.":{"zh":"位移拟态的核心起初悬浮在空中，且极为沉重。玩家可以激活月球重力装置，将其移回。\n激活后，玩家重力大幅降低，进入月球状态下的角色、摄像机与操控模式，并在碰撞周围物体时触发物理反馈。","en":"The core of the \"Displaced Mimic\" is in the air at the very beginning and is extremely heavy. Players can move it back by activating the \"Lunar Gravity\" device.\n\nAfter lunar gravity is activated, the player's gravity is drastically reduced, entering Lunar State 3C, and physical feedback is triggered upon collision with surrounding objects."},"I use radial blur and posterization post-processing effects to visualize gravity shifts.":{"zh":"我使用径向模糊与色阶分离后处理，将重力变化可视化。","en":"I use radial blur and posterization post-processing effects to visualize gravity shifts."},"NPC Mini Games":{"zh":"角色互动小游戏","en":"NPC Mini Games"},"Zero-Gravity Zone":{"zh":"失重区域","en":"Zero-Gravity Zone"},"A derelict zero-gravity zone exists aboard a spaceship, where numerous workers are trapped. Upon entering the zone, the player will enter Zero-Gravity State 3C.":{"zh":"飞船内有一片废弃的失重区域，许多工人被困其中。玩家进入后，将切换到失重状态下的角色、摄像机与操控模式。","en":"A derelict zero-gravity zone exists aboard a spaceship, where numerous workers are trapped. Upon entering the zone, the player will enter Zero-Gravity State 3C."},"When the player approaches a trapped NPC, they can interact to connect to their lifeline, then leverage the physics of the zero-gravity zone to pull them along.":{"zh":"玩家靠近被困角色时，可以交互并连接其生命绳，利用失重区域的物理特性将其拖走。","en":"When the player approaches a trapped NPC, they can interact to connect to their lifeline, then leverage the physics of the zero-gravity zone to pull them along."},"Open World Puzzles & NPC Minigames":{"zh":"开放世界谜题与角色互动小游戏","en":"Open World Puzzles & NPC Minigames"},"Magnetic Attractor: In the zero-gravity zone, this is the only device the player can use for movement.":{"zh":"磁力吸引器：在失重区域中，这是玩家唯一可用于移动的装置。","en":"Magnetic Attractor: In the zero-gravity zone, this is the only device the player can use for movement."},"Batesian Bugs":{"zh":"拟态虫","en":"Batesian Bugs"},"Stand by the police, try to spot the keywords uttered by passing NPCs and arrest them with a shooting motion.":{"zh":"站在警察身旁，从路过角色的话语中识别关键词，再通过射击动作将目标逮捕。","en":"Stand by the police, try to spot the keywords uttered by passing NPCs and arrest them with a shooting motion."},"Some anthropomorphic bugs blend in with the NPCs. A close look reveals their absurdly comical deformities. When players spot them and interact to talk with them, the bugs will revert to their original form.":{"zh":"一些拟人化虫子混入了人群，仔细观察会发现其滑稽、夸张的畸形特征。玩家发现并与之对话后，虫子会恢复原形。","en":"Some anthropomorphic bugs blend in with the NPCs. A close look reveals their absurdly comical deformities. When players spot them and interact to talk with them, the bugs will revert to their original form."},"The bizarre appearances of these NPCs are all modified using the UE Animation System.":{"zh":"这些角色的奇异外观均通过虚幻引擎动画系统进行修改。","en":"The bizarre appearances of these NPCs are all modified using the UE Animation System."},"Gameplay System Design":{"zh":"玩法系统设计","en":"Gameplay System Design"},"Reference: Outer Wilds, No Man’s Sky,Starfield...":{"zh":"参考：《星际拓荒》《无人深空》《星空》等。","en":"Reference: Outer Wilds, No Man’s Sky,Starfield..."},"Signal Scanner Gameplay":{"zh":"信号扫描器玩法","en":"Signal Scanner Gameplay"},"In Kailo, players can open their signal Scanner to search if there’s special sites, missing people, or misterious treasures...":{"zh":"在卡洛，玩家可以打开信号扫描器，搜索特殊地点、失踪人员和神秘宝藏。","en":"In Kailo, players can open their signal Scanner to search if there’s special sites, missing people, or misterious treasures..."},"Signal Scanner & Exploration":{"zh":"信号扫描器与探索","en":"Signal Scanner & Exploration"},"Background: 5.0 Vast Vertical Space Map+ Short Draw Distance = Difficulty in Locating POIs —→ Our team placed most gameplay elements and POIs near the main asteroid belt. —→ My responsibility was to use off-the-beaten-path areas to create side missions.":{"zh":"背景：5.0 版本的地图纵向空间巨大，但绘制距离较短，兴趣点难以定位。\n因此，团队将大部分玩法与兴趣点放在主小行星带附近。\n我负责利用偏离主路径的区域制作支线任务。","en":"Background: 5.0 Vast Vertical Space Map+ Short Draw Distance = Difficulty in Locating POIs\n—→ Our team placed most gameplay elements and POIs near the main asteroid belt.\n—→ My responsibility was to use off-the-beaten-path areas to create side missions."},"That’s how I designed this system...":{"zh":"我由此设计了这套系统。","en":"That’s how I designed this system..."},"Simultaneously, I needed to guide players to locate mission destinations with relative precision. To achieve this, a scanner system was designed, which further extended into two gameplay features: finding missing persons and treasure maps.":{"zh":"同时，还需要相对精确地引导玩家抵达任务地点。因此，我设计了扫描器系统，并进一步扩展出寻找失踪人员和藏宝图两种玩法。","en":"Simultaneously, I needed to guide players to locate mission destinations with relative precision. To achieve this, a scanner system was designed, which further extended into two gameplay features: finding missing persons and treasure maps."},"Signal towers are scattered across the map and capable of emitting signals. When the player activates the scanner, the scanner interface is triggered, displaying icons of signal towers emitting signals within a 1km radius for the player to track. Special Unknown Signal Towers do not show their icons directly; their location and tracking require the induction ring on the main interface. When the player aims at an active signal tower, they can obtain signal information":{"zh":"地图上分布着能够发出信号的信号塔。玩家开启扫描器后，会进入扫描界面，显示一公里范围内正在发射信号的信号塔图标，供玩家追踪。\n特殊的未知信号塔不会直接显示图标，需要通过主界面的感应环定位和追踪。\n玩家瞄准已激活的信号塔时，可以读取信号信息。","en":"Signal towers are scattered across the map and capable of emitting signals. When the player activates the scanner, the scanner interface is triggered, displaying icons of signal towers emitting signals within a 1km radius for the player to track.\n\nSpecial Unknown Signal Towers do not show their icons directly; their location and tracking require the induction ring on the main interface. \n\nWhen the player aims at an active signal tower, they can obtain signal information"},"I've been contemplating how the cosmic-themed games drive player exploration. They seem to employ an instrument that maintains a connection with every corner of the world, yet its effectiveness hinges on careful observation and a degree of luck.":{"zh":"我一直在思考宇宙题材游戏如何驱动探索。这些游戏似乎通过一种仪器，让玩家与世界各处保持联系，但仪器是否有效，还取决于仔细观察和一定的运气。","en":"I've been contemplating how the cosmic-themed games drive player exploration. They seem to employ an instrument that maintains a connection with every corner of the world, yet its effectiveness hinges on careful observation and a degree of luck."},"I have deeply considered integrating the exploration-driven missing persons missions from Dying Light with the fragmented storytelling approach of Dark Souls. This design allows players to efficiently uncover and piece together a complete backstory while exploring the world.":{"zh":"我深入思考过，将《消逝的光芒》中探索驱动的寻人任务与《黑暗之魂》的碎片化叙事结合，让玩家在探索世界时逐步发现线索，拼出完整背景故事。","en":"I have deeply considered integrating the exploration-driven missing persons missions from Dying Light with the fragmented storytelling approach of Dark Souls. This design allows players to efficiently uncover and piece together a complete backstory while exploring the world."},"Finding Missing People Gameplay":{"zh":"寻找失踪人员玩法","en":"Finding Missing People Gameplay"},"Players can find three Missing Persons Archives in three urban districts. → Open the panel to check the missing person’s last-seen district. → Tap Record to save the info to the scanner. Go to the district, activate the scanner to find last sighting A, then head there. → At A, reactivate the scanner to track the Unknown Signal Tower toward the actual location B. → Reach B and trigger an event (dialogue rescue, monster battle rescue, corpse discovery – increasing in complexity). → Return to the Archive, tap the photo to claim rewards.":{"zh":"玩家可以在三个城区找到三处失踪人员档案。\n→ 打开面板，查看失踪者最后出现的城区。\n→ 点击记录，将信息保存到扫描器，前往对应城区扫描并找到最后出现点甲。\n→ 到达甲点后再次扫描，追踪未知信号塔，前往实际位置乙。\n→ 到达乙点并触发事件，如对话救援、战斗救援或发现尸体，复杂度逐步增加。\n→ 返回档案，点击照片领取奖励。","en":"Players can find three Missing Persons Archives in three urban districts.\n→ Open the panel to check the missing person’s last-seen district.\n→ Tap Record to save the info to the scanner. Go to the district, activate the scanner to find last sighting A, then head there.\n→ At A, reactivate the scanner to track the Unknown Signal Tower toward the actual location B.\n→ Reach B and trigger an event (dialogue rescue, monster battle rescue, corpse discovery – increasing in complexity).\n→ Return to the Archive, tap the photo to claim rewards."},"Record the info, then locate Jerry’s signal point. Reach the signal tower and find it’s a mutated Batesian Bug.":{"zh":"记录信息后，定位杰里的信号点。抵达信号塔时，发现目标是一只变异拟态虫。","en":"Record the info, then locate Jerry’s signal point. Reach the signal tower and find it’s a mutated Batesian Bug."},"Level Design Of Finding Missing People":{"zh":"寻人玩法的关卡设计","en":"Level Design Of Finding Missing People"},"Sorted by Event Type: Minimize repetitive gameplay; Intersperse several event types across 3 panels. Sorted by Difficulty of Discovery: Establish difficulty gradients based on proximity to critical paths, distinctness of elevation changes and event complexity. The lowest difficulty is assigned to the Novice Village panel. Sorted by Narrative: The farther a missing person is from the main path, the higher their chance of death.":{"zh":"按事件类型：减少重复玩法，在三块面板中穿插不同事件。\n按发现难度：根据主路径距离、高差辨识度和事件复杂度建立梯度，新手村面板的难度最低。\n按叙事：失踪者距离主路径越远，死亡概率越高。","en":"Sorted by Event Type: Minimize repetitive gameplay; Intersperse several event types across 3 panels.\nSorted by Difficulty of Discovery: Establish difficulty gradients based on proximity to critical paths, distinctness of elevation changes and event complexity. The lowest difficulty is assigned to the Novice Village panel.\nSorted by Narrative: The farther a missing person is from the main path, the higher their chance of death."},"Example Story Of Finding Missing People":{"zh":"寻人玩法的故事示例","en":"Example Story Of Finding Missing People"},"Locate an unknown signal point nearby.":{"zh":"定位附近的未知信号点。","en":"Locate an unknown signal point nearby."},"Arrive there to discover Jerry’s body and his final message, learning he has a daughter. You can later talk to his daughter to trigger more story content.":{"zh":"抵达后发现杰里的尸体与遗言，得知他还有一名女儿。\n后续可以与女儿对话，触发更多故事。","en":"Arrive there to discover Jerry’s body and his final message, learning he has a daughter.\nYou can later talk to his daughter to trigger more story content."},"Finding Secret Treasures":{"zh":"寻找秘密宝藏","en":"Finding Secret Treasures"},"→ Get pirate treasure map location & password from NPC; minimap marks the spot, scanner logs the map’s signal. → Near the target: thick fog + strange meteorites spawn; activate scanner to locate the treasure spot. → Reach the treasure spot’s signal tower → prompt: numerous unknown signals nearby. → Scan to find 4 unknown signals with different password messages each. → Dig at the wrong password → teleported to wormhole (penalty). → Dig at the NPC’s password → claim reward.":{"zh":"→ 从角色处获得海盗藏宝地点与密码，小地图标记位置，扫描器记录藏宝图信号。\n→ 接近目标时出现浓雾与奇异陨石，开启扫描器定位宝藏。\n→ 抵达宝藏信号塔，收到附近有大量未知信号的提示。\n→ 扫描找到四个未知信号，各自给出不同密码信息。\n→ 按错误密码挖掘，会被传送进虫洞作为惩罚。\n→ 按角色提供的密码挖掘，即可领取奖励。","en":"→ Get pirate treasure map location & password from NPC; minimap marks the spot, scanner logs the map’s signal.\n→ Near the target: thick fog + strange meteorites spawn; activate scanner to locate the treasure spot.\n→ Reach the treasure spot’s signal tower → prompt: numerous unknown signals nearby.\n→ Scan to find 4 unknown signals with different password messages each.\n→ Dig at the wrong password → teleported to wormhole (penalty).\n→ Dig at the NPC’s password → claim reward."},"Gameplay Video: https://www.youtube.com/watch?v=WsN8uDmADYQ":{"zh":"玩法视频：https://www.youtube.com/watch?v=WsN8uDmADYQ","en":"Gameplay Video: https://www.youtube.com/watch?v=WsN8uDmADYQ"},"Other Mini Games I Designed":{"zh":"我设计的其他小游戏","en":"Other Mini Games I Designed"},"During my time working on Tower of Fantasy, I also designed a number of other mini-games, which were widely praised by players both at home and abroad.":{"zh":"在《幻塔》工作期间，我还设计了多种其他小游戏，获得国内外玩家的广泛好评。","en":"During my time working on Tower of Fantasy, I also designed a number of other mini-games, which were widely praised by players both at home and abroad."},"Bot Head Golf":{"zh":"机械头高尔夫","en":"Bot Head Golf"},"Illusory Bubble":{"zh":"幻影泡泡","en":"Illusory Bubble"},"If you dream of getting rich overnight, or find the burden of common prosperity too heavy and crave excitement instead.":{"zh":"如果你梦想一夜暴富，或觉得共同富裕的负担太重，想寻求一点刺激。","en":"If you dream of getting rich overnight, or find the burden of common prosperity too heavy and crave excitement instead."},"A golf game loved by Brighton District (rich part) executives: calculate the correct sequence and path to send the metal noggin through the portal and fly to the finish line.":{"zh":"布莱顿富人区高管喜爱的高尔夫游戏：计算正确顺序与路径，让金属脑袋穿过传送门，飞向终点。","en":"A golf game loved by Brighton District (rich part) executives: calculate the correct sequence and path to send the metal noggin through the portal and fly to the finish line."},"Paper Plane":{"zh":"纸飞机","en":"Paper Plane"},"Phantom Beat":{"zh":"幻影节拍","en":"Phantom Beat"},"https://www.youtube.com/watch?v=mIEa2wznzYA":{"zh":"https://www.youtube.com/watch?v=mIEa2wznzYA","en":"https://www.youtube.com/watch?v=mIEa2wznzYA"},"https://www.youtube.com/watch?v=LbXMCyPJ8NY":{"zh":"https://www.youtube.com/watch?v=LbXMCyPJ8NY","en":"https://www.youtube.com/watch?v=LbXMCyPJ8NY"},"Express yourself on the dance floor, follow Lana’s phantom figure, and dance together to the rhythm and beat.":{"zh":"在舞池中展现自我，跟随拉娜的幻影，伴着节奏与节拍一起舞动。","en":"Express yourself on the dance floor, follow Lana’s phantom figure, and dance together to the rhythm and beat."},"When the player throws the plane, they can view the scenery along the plane’s path in first-person perspective.":{"zh":"玩家投出纸飞机后，可以用第一人称视角欣赏沿途风景。","en":"When the player throws the plane, they can view the scenery along the plane’s path in first-person perspective."},"Random NPC Tools":{"zh":"随机角色生成工具","en":"Random NPC Tools"},"During the Tower of Fantasy project, to improve the configuration efficiency of open-world levels, I independently used UE tool control blueprints to create some tool buttons that facilitate enhancing the open-world mass placement efficiency.":{"zh":"在《幻塔》项目中，为了提高开放世界关卡配置效率，我独立使用虚幻引擎的编辑器工具蓝图制作了一组工具按钮，提升开放世界的批量布置效率。","en":"During the Tower of Fantasy project, to improve the configuration efficiency of open-world levels, I independently used UE tool control blueprints to create some tool buttons that facilitate enhancing the open-world mass placement efficiency."},"Minigames & NPC Tools":{"zh":"小游戏与角色工具","en":"Minigames & NPC Tools"},"One-Click Random Spawn Generation Tool：Uniformly distributed Targets within an area or generated them procedurally from scene models and logic, then batch-assigned to spawners. Configuration Table Export Tool：Batch-exported setup data to tables for streamlined testing. One-Click-to-Load Specific Level Layers Tool：Dragging an Actor auto-loaded the corresponding streaming level at those coordinates and set it active.":{"zh":"一键随机生成工具：在区域内均匀分布目标点，或根据场景模型与逻辑程序化生成目标，再批量分配给生成器。\n配置表导出工具：批量将配置数据导出至表格，便于测试。\n一键加载指定关卡层工具：拖动场景对象即可自动加载对应坐标的流式关卡，并设为当前关卡。","en":"One-Click Random Spawn Generation Tool：Uniformly distributed Targets within an area or generated them procedurally from scene models and logic, then batch-assigned to spawners.\n\nConfiguration Table Export Tool：Batch-exported setup data to tables for streamlined testing.\n\nOne-Click-to-Load Specific Level Layers Tool：Dragging an Actor auto-loaded the corresponding streaming level at those coordinates and set it active."},"(These tools were developed by me personally, but certain shared nodes have been obscured in presentation.)":{"zh":"这些工具由我独立开发，展示时对部分共用节点进行了遮挡。","en":"(These tools were developed by me personally, but certain shared nodes have been obscured in presentation.)"},"Procedural dummy NPC generation: Batch-generated NPC instances with variations in position, model, and animation based on data tables, supporting batch material replacement for color variation and sequential assignment of movement targets. This system utilizes multiple configurable Data Tables, allowing designers to flexibly modify parameters such as NPC types spawnable in specific areas and required mood-based animations.":{"zh":"程序化占位角色生成：根据数据表批量生成不同位置、模型和动画的角色实例，支持批量替换材质以改变颜色，并按顺序分配移动目标。\n系统使用多个可配置数据表，让设计师灵活调整特定区域允许生成的角色类型，以及不同情绪对应的动画等参数。","en":"Procedural dummy NPC generation: Batch-generated NPC instances with variations in position, model, and animation based on data tables, supporting batch material replacement for color variation and sequential assignment of movement targets. \n\nThis system utilizes multiple configurable Data Tables, allowing designers to flexibly modify parameters such as NPC types spawnable in specific areas and required mood-based animations."},"Individual Project · Full-pipeline stylized scene · PCG + Substance Designer":{"zh":"个人项目 · 风格化场景全流程 · 程序化生成与 Substance Designer","en":"Individual Project · Full-pipeline stylized scene · PCG + Substance Designer"},"Slope Blur Edge Wear + Flood Fill + Curvature Edge Highlights":{"zh":"斜率模糊边缘磨损、泛洪填充与曲率边缘高光","en":"Slope Blur Edge Wear + Flood Fill + Curvature Edge Highlights"},"Reference":{"zh":"参考","en":"Reference"},"Substance Designer graph":{"zh":"Substance Designer 节点图","en":"Substance Designer graph"},"Result":{"zh":"结果","en":"Result"},"Tile Sampler + Flood Fill":{"zh":"平铺采样器与泛洪填充","en":"Tile Sampler + Flood Fill"},"In scene":{"zh":"场景中","en":"In scene"},"Brushstroke Touches":{"zh":"笔触细节","en":"Brushstroke Touches"},"Brushstroke graph":{"zh":"笔触节点图","en":"Brushstroke graph"},"Brushstroke texture":{"zh":"笔触纹理","en":"Brushstroke texture"},"From another project":{"zh":"来自另一个项目","en":"From another project"},"Procedural feature":{"zh":"程序化功能","en":"Procedural feature"},"Users only need to place two cubes—one to generate a brick wall based on Cube 1's transform, and another to create a door based on Cube 2's transform. When the material texture of the wall is modified, the wall model updates accordingly. It streamlines the workflow by eliminating the need for manual modeling of complex brick walls. Parameters — Bricks: Brick Tile Scale, Brick Height. Door: Has Door, Door Bevel Distance, Door Bevel Division, Door Width. Top Edge: Top Edge Width, Top Edge Scale.":{"zh":"用户只需放置两个立方体，一个根据第一个立方体的变换生成砖墙，另一个根据第二个立方体的变换生成门。修改墙体材质纹理后，模型会同步更新，无须手工搭建复杂砖墙。\n参数：砖块的平铺比例与高度；门的生成开关、倒角距离、倒角分段与宽度；顶边的宽度与缩放。","en":"Users only need to place two cubes—one to generate a brick wall based on Cube 1's transform, and another to create a door based on Cube 2's transform. When the material texture of the wall is modified, the wall model updates accordingly. It streamlines the workflow by eliminating the need for manual modeling of complex brick walls.\nParameters — Bricks: Brick Tile Scale, Brick Height. Door: Has Door, Door Bevel Distance, Door Bevel Division, Door Width. Top Edge: Top Edge Width, Top Edge Scale."},"Generated wall":{"zh":"生成的墙体","en":"Generated wall"},"Node network":{"zh":"节点网络","en":"Node network"},"Brick parameters":{"zh":"砖块参数","en":"Brick parameters"},"Door parameters":{"zh":"门参数","en":"Door parameters"},"Top-edge parameters":{"zh":"顶边参数","en":"Top-edge parameters"},"Mesh from SD material":{"zh":"由程序材质生成网格","en":"Mesh from SD material"},"Nodes":{"zh":"节点","en":"Nodes"},"Advanced Workflow":{"zh":"进阶流程","en":"Advanced Workflow"},"I used Blast to extract specific faces of a cube, Boolean to cut out the door opening, and finally Sweep to generate the door frame, top trim, and related structural details.":{"zh":"使用删除节点提取立方体的指定面，再通过布尔运算切出门洞，最后使用扫掠生成门框、顶部饰边及其他结构细节。","en":"I used Blast to extract specific faces of a cube, Boolean to cut out the door opening, and finally Sweep to generate the door frame, top trim, and related structural details."},"Boolean door":{"zh":"布尔切割门洞","en":"Boolean door"},"Door curve":{"zh":"门洞曲线","en":"Door curve"},"Sweep frame":{"zh":"扫掠门框","en":"Sweep frame"},"Preview Mode Set":{"zh":"预览模式设置","en":"Preview Mode Set"},"I separated performance-intensive nodes using a Switch, allowing users to adjust parameters in Preview Mode first, then toggle the FinalResult button to view the final outcome.":{"zh":"通过切换节点隔离开销较大的节点，让用户先在预览模式中调整参数，再切换到最终结果查看完整模型。","en":"I separated performance-intensive nodes using a Switch, allowing users to adjust parameters in Preview Mode first, then toggle the FinalResult button to view the final outcome."},"Preview mode":{"zh":"预览模式","en":"Preview mode"},"Final result":{"zh":"最终结果","en":"Final result"},"Debugging position and shape in Preview Mode":{"zh":"在预览模式中调试位置与形状","en":"Debugging position and shape in Preview Mode"},"Click Is Final Result to generate the actual model":{"zh":"勾选最终结果，生成实际模型","en":"Click Is Final Result to generate the actual model"},"Parameters":{"zh":"参数","en":"Parameters"},"The wall's overall length, width, and height can be adjusted, along with the individual stone's length, width, height, and the degree of weathering or breakage.":{"zh":"可调节墙体整体的长宽高，以及单块石头的长宽高和风化、破损程度。","en":"The wall's overall length, width, and height can be adjusted, along with the individual stone's length, width, height, and the degree of weathering or breakage."},"Stone wall":{"zh":"石墙","en":"Stone wall"},"For Loop per Stone":{"zh":"逐块石头循环","en":"For Loop per Stone"},"Per-stone variation":{"zh":"单块石头变化","en":"Per-stone variation"},"For Loop nodes":{"zh":"循环节点","en":"For Loop nodes"},"Key Node: Point Wrangle":{"zh":"关键节点：点处理","en":"Key Node: Point Wrangle"},"Using Point Wrangle to script a pattern: modify the point positions of odd-numbered primitives based on the vector between adjacent points and a given length, then add extra points and polylines. This enables staggered placement of stones.":{"zh":"在点处理节点中编写脚本，根据相邻点之间的向量和给定长度，修改奇数编号图元的点位置，并添加额外的点和折线，从而实现石块的错缝排列。","en":"Using Point Wrangle to script a pattern: modify the point positions of odd-numbered primitives based on the vector between adjacent points and a given length, then add extra points and polylines. This enables staggered placement of stones."},"Staggered points":{"zh":"错位的点","en":"Staggered points"},"VEX & nodes":{"zh":"VEX 脚本与节点","en":"VEX & nodes"},"Drag / adjust spline":{"zh":"拖动／调整样条","en":"Drag / adjust spline"},"Spline in scene":{"zh":"场景中的样条","en":"Spline in scene"},"Adjust the effect in Preview Mode":{"zh":"在预览模式中调整效果","en":"Adjust the effect in Preview Mode"},"Use various nodes to sculpt the overall form, then enhance it with a HeightField Erode node and auto-coloration.":{"zh":"使用多种节点塑造山体整体形态，再通过高度场侵蚀节点与自动着色增强效果。","en":"Use various nodes to sculpt the overall form, then enhance it with a HeightField Erode node and auto-coloration."},"Mountain range":{"zh":"山脉","en":"Mountain range"},"Base form":{"zh":"基础形态","en":"Base form"},"HeightField Erode":{"zh":"高度场侵蚀","en":"HeightField Erode"},"Layered Mountain Forms":{"zh":"分层山体","en":"Layered Mountain Forms"},"I utilized Sweep combined with Mix by Attribute node to create layered mountain forms and blend terrain at varying elevations. The result is exported as a HeightMap for use in Unreal Engine.":{"zh":"结合扫掠与按属性混合节点，创建分层山体，并混合不同高度的地形。最终导出高度图，在虚幻引擎中使用。","en":"I utilized Sweep combined with Mix by Attribute node to create layered mountain forms and blend terrain at varying elevations. The result is exported as a HeightMap for use in Unreal Engine."},"Layered forms":{"zh":"分层形态","en":"Layered forms"},"Sweep result":{"zh":"扫掠结果","en":"Sweep result"},"Mix by Attribute":{"zh":"按属性混合","en":"Mix by Attribute"},"Exported HeightMap":{"zh":"导出的高度图","en":"Exported HeightMap"},"Thought Process":{"zh":"设计思路","en":"Thought Process"},"Another attempt involved adding elements like rivers, but it felt too realistic and was ultimately not adopted.":{"zh":"也尝试过加入河流等元素，但效果过于写实，最终没有采用。","en":"Another attempt involved adding elements like rivers, but it felt too realistic and was ultimately not adopted."},"River attempt (not adopted)":{"zh":"河流尝试：未采用","en":"River attempt (not adopted)"},"Cabin model":{"zh":"小屋模型","en":"Cabin model"},"Runtime Virtual Texturing Grass":{"zh":"运行时虚拟纹理草地","en":"Runtime Virtual Texturing Grass"},"RVT makes the grass blend more naturally with the landscape.":{"zh":"运行时虚拟纹理让草地与地形的衔接更加自然。","en":"RVT makes the grass blend more naturally with the landscape."},"RVT textures":{"zh":"运行时虚拟纹理贴图","en":"RVT textures"},"Material":{"zh":"材质","en":"Material"},"Vertex-color stone wall":{"zh":"顶点色石墙","en":"Vertex-color stone wall"},"Detail":{"zh":"细节","en":"Detail"},"Material ball":{"zh":"材质球","en":"Material ball"},"Original reference":{"zh":"原始参考","en":"Original reference"},"First pass":{"zh":"初版","en":"First pass"},"Realistic brick":{"zh":"写实砖墙","en":"Realistic brick"},"Before":{"zh":"修改前","en":"Before"},"After":{"zh":"修改后","en":"After"},"Final":{"zh":"最终版","en":"Final"},"Scene iteration":{"zh":"场景迭代","en":"Scene iteration"},"Unreal Engine":{"zh":"Unreal Engine","en":"Unreal Engine"},"Meta Quest 3":{"zh":"Meta Quest 3","en":"Meta Quest 3"},"VR":{"zh":"虚拟现实","en":"VR"},"Shader":{"zh":"Shader","en":"Shader"},"Art Deco":{"zh":"装饰艺术","en":"Art Deco"},"Shading":{"en":"Shading","zh":"着色"},"Showreel":{"zh":"作品混剪","en":"Showreel"},"Iteration":{"en":"Iteration","zh":"迭代"},"Render":{"en":"Render","zh":"渲染"},"Remaster":{"en":"Remaster","zh":"重制"},"PCG":{"zh":"程序化生成","en":"PCG"},"Procedural":{"zh":"程序化","en":"Procedural"},"Tool":{"en":"Tool","zh":"工具"},"PBR Shaders":{"en":"PBR Shaders","zh":"PBR Shader"},"Shadow Man":{"en":"Shadow Man","zh":"暗影人"},"Lycorius Shader Iteration":{"en":"Lycorius Shader Iteration","zh":"彼岸花Shader迭代"},"Lycorius Shader 迭代":{"en":"Lycorius Shader Iteration","zh":"彼岸花Shader迭代"},"Laputa · 天空之城":{"en":"Laputa","zh":"天空之城"},"Inside The Paper":{"en":"Inside The Paper","zh":"纸中世界"},"Behind Me":{"en":"Behind Me","zh":"身后"},"Shader Shading Showreel":{"en":"Shader Shading Showreel","zh":"Shader效果混剪"},"Shader / Shading / Showreel":{"en":"Shader / Shading / Showreel","zh":"Shader／着色／作品混剪"},"Technical Artist":{"en":"Technical Artist","zh":"技术美术师"},"Preview":{"en":"Preview","zh":"预览"},"Close":{"en":"Close","zh":"关闭"},"About":{"en":"About","zh":"关于"},"About Me":{"en":"About Me","zh":"关于我"},"Skills":{"en":"Skills","zh":"技能"},"Featured Works":{"en":"Featured Works","zh":"精选作品"},"Scroll":{"en":"Scroll","zh":"向下滚动"},"Project Case Study":{"en":"Project Case Study","zh":"项目详情"}};
  function key(s){return s.replace(/\s+/g,' ').trim();}
  function text(value,lang){
    lang=lang==='zh'?'zh':'en';
    if(value==null)return '';
    var source=typeof value==='object'?(value[lang]||value.en||value.zh||''):String(value);
    var pair=copy[key(source)];return pair?pair[lang]:source;
  }
  window.SiteCopy={text:text,entries:copy};
})();
